// single-item input: one form submission, one list of handles.
const cfg = $('Settings').first().json;
const form = $('Paste The Handles').first().json;

const raw = String(form['Instagram handles'] || '');
const max_creators = Math.max(1, Number(cfg.max_creators) || 8);
const posts_per = Math.max(3, Number(cfg.posts_per_creator) || 12);

// People paste whatever is on their clipboard: @name, name, the profile URL
// with a trailing slash, the URL with an igshid query string on the end. The
// dataset takes exactly one of those, so everything is reduced to a bare handle
// first and rebuilt into the canonical URL after.
const seen = {};
const handles = [];
const rejected = [];
for (const piece of raw.split(/[\s,;]+/)) {
  const trimmed = String(piece || '').trim();
  if (!trimmed) continue;
  let handle = trimmed.replace(/^@/, '');
  const from_url = handle.match(/instagram\.com\/([^/?#]+)/i);
  if (from_url) handle = from_url[1];
  handle = handle.replace(/\/+$/, '').trim().toLowerCase();
  if (!/^[a-z0-9._]{1,30}$/.test(handle)) {
    rejected.push(trimmed);
    continue;
  }
  if (seen[handle]) continue;
  seen[handle] = true;
  handles.push(handle);
}

const kept = handles.slice(0, max_creators);
const over_limit = handles.slice(max_creators);

const url_for = (h) => 'https://www.instagram.com/' + h + '/';

return [
  {
    json: {
      handles: kept,
      rejected: rejected,
      over_limit: over_limit,
      what_you_sell: String(form['What you sell'] || '').trim(),
      budget_per_post: Number(form['Budget per post']) || 0,
      posts_per_creator: posts_per,
      payload_profiles: kept.map((h) => ({ url: url_for(h) })),
      // The posts dataset only discovers on `url`. `profile_url`, `keyword` and
      // `hashtag` are all rejected with the list of types it does support.
      payload_posts: kept.map((h) => ({
        url: url_for(h),
        num_of_posts: posts_per,
        start_date: '',
        end_date: '',
        post_type: '',
      })),
    },
  },
];

// Bright Data answers a validation error with HTTP 200 and an error body, so a
// green node upstream means nothing on its own. Both snapshot ids are read back
// here and a refusal is carried forward as a job with no id rather than thrown,
// because the person who submitted the form is still waiting on the page and
// deserves the reason rather than a red node they cannot see.
function readJob(nodeName, label) {
  const raw = $(nodeName).first().json || {};
  const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
  const snapshot_id = body.snapshot_id || '';
  let error = '';
  if (!snapshot_id) {
    error =
      String(body.error || body.message || 'no snapshot_id returned') +
      (body.errors ? ' ' + JSON.stringify(body.errors).slice(0, 200) : '');
  }
  return { job: label, snapshot_id: snapshot_id, error: error };
}

return [
  { json: readJob('Ask For The Profiles', 'profiles') },
  { json: readJob('Ask For Recent Posts', 'posts') },
];

const cfg = $('Settings').first().json;
const jobs = $('Track Both Jobs').all().map((i) => i.json);
const max_polls = Math.max(2, Number(cfg.max_polls) || 20);

// $runIndex is how many times this node has run in this execution, which is the
// poll count. Without a cap a snapshot that never finishes spins the loop until
// the execution is killed, and on a form-triggered run that is a browser tab
// waiting forever.
const polls = $runIndex + 1;
const timed_out = polls >= max_polls;

const status_by_id = {};
for (const item of $input.all()) {
  const raw = item.json || {};
  const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
  if (body && body.snapshot_id) {
    status_by_id[body.snapshot_id] = String(body.status || '');
  }
}

let waiting = 0;
const out = [];
for (const job of jobs) {
  const status = job.snapshot_id ? status_by_id[job.snapshot_id] || 'running' : 'refused';
  if (status === 'running' || status === 'collecting' || status === 'building') waiting += 1;
  out.push({ ...job, status: status });
}

// A job Bright Data refused has no snapshot to wait for, so a run where both
// were refused finishes immediately with an explanation instead of polling a
// pair of ids that do not exist.
const all_ready = waiting === 0 || timed_out;
return out.map((row) => ({
  json: { ...row, all_ready: all_ready, timed_out: timed_out && waiting > 0, polls: polls },
}));

// Both snapshots are downloaded by the same node, one HTTP request per job, and
// n8n splits each JSON array response into one item per row. So this receives
// profile rows and post rows mixed together with nothing labelling which is
// which - they are told apart by shape: a post row has a numeric `likes`, a
// profile row has `followers` and `posts_count` and no likes at all.
const clean = $('Clean The Handles').first().json;
const jobs = $('Are They Ready?').all().map((i) => i.json);
const requested = clean.handles || [];

const refused = jobs.filter((j) => !j.snapshot_id).map((j) => j.job + ': ' + j.error);
const timed_out = jobs.some((j) => j.timed_out);

const profiles = {};
const posts_by_handle = {};
let coauthor_dropped = 0;
let download_error = '';

const handleFromUrl = (u) => {
  const m = String(u || '').match(/instagram\.com\/([^/?#]+)/i);
  return m ? m[1].toLowerCase() : '';
};

for (const item of $input.all()) {
  const row = item.json || {};
  if (row.error || row.message) {
    // A snapshot that is not ready answers with an error body and HTTP 200,
    // because the request node is set to never error.
    download_error = String(row.error || row.message).slice(0, 200);
    continue;
  }
  if (typeof row.likes === 'number' || typeof row.num_comments === 'number') {
    // Discovery is per profile URL, so `discovery_input.url` is the handle that
    // was asked for. `user_posted` is who actually posted it, and the two differ
    // whenever a co-author account is involved.
    const asked = handleFromUrl((row.discovery_input && row.discovery_input.url) || (row.input && row.input.url));
    const author = String(row.user_posted || '').toLowerCase();
    if (!asked) continue;
    if (author && author !== asked) {
      coauthor_dropped += 1;
      continue;
    }
    (posts_by_handle[asked] = posts_by_handle[asked] || []).push(row);
    continue;
  }
  if (row.account || row.profile_url) {
    const handle = String(row.account || handleFromUrl(row.profile_url || row.url)).toLowerCase();
    if (handle) profiles[handle] = row;
  }
}

// Built from the list that was requested, not from the rows that came back. A
// handle that no longer exists returns no row at all, and iterating the
// response would silently drop the one the person most wants to hear about.
return requested.map((handle) => ({
  json: {
    handle: handle,
    profile: profiles[handle] || null,
    posts: posts_by_handle[handle] || [],
    found: Boolean(profiles[handle]),
    refused: refused,
    timed_out: timed_out,
    download_error: download_error,
    coauthor_dropped: coauthor_dropped,
  },
}));

const cfg = $('Settings').first().json;
const clean = $('Clean The Handles').first().json;
const history = $('Read The Vetting History').all().map((i) => i.json);

const budget = Number(clean.budget_per_post) || 0;
const min_followers = Number(cfg.min_followers) || 0;
const max_followers = Number(cfg.max_followers) || 0;
const min_er = Number(cfg.min_engagement_pct) || 0;
const max_er = Number(cfg.max_engagement_pct) || 0;
const min_comment_ratio = Number(cfg.min_comment_ratio_pct) || 0;
const max_sponsored = Number(cfg.max_sponsored_pct) || 100;
const max_quiet_days = Number(cfg.max_days_since_post) || 0;
const min_posts = Math.max(3, Number(cfg.min_posts_to_judge) || 5);

const prior = {};
for (const row of history) {
  if (row && row.handle) prior[String(row.handle).toLowerCase()] = row;
}

const round = (n, dp) => {
  const f = Math.pow(10, dp);
  return Math.round((Number(n) || 0) * f) / f;
};

const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const flags = [];
  const profile = d.profile || {};

  if (!d.found) {
    out.push({
      json: {
        handle: d.handle,
        profile_url: 'https://www.instagram.com/' + d.handle + '/',
        found: false,
        lane: 'no_data',
        reason: d.refused.length
          ? 'Bright Data refused the request - ' + d.refused.join('; ')
          : d.timed_out
            ? 'Instagram did not answer in time'
            : 'no profile came back for this handle - check the spelling, or the account is gone',
        flags: ['not_found'],
        // The extractor downstream reads these off every item. A creator that
        // was never found still passes through it, so they are present and
        // empty rather than undefined.
        biography: '',
        captions: [],
        comment_sample: [],
        refused: d.refused,
        timed_out: d.timed_out,
        coauthor_dropped: d.coauthor_dropped,
        what_you_sell: clean.what_you_sell,
        budget_per_post: budget,
      },
    });
    continue;
  }

  // The denominator, and the reason the profile dataset is called at all. Post
  // rows carry their own `followers`, rounded to the nearest million.
  const followers = Number(profile.followers) || 0;
  const posts = (d.posts || []).slice().sort((a, b) => String(b.date_posted || '').localeCompare(String(a.date_posted || '')));

  const engagements = posts.map((p) => (Number(p.likes) || 0) + (Number(p.num_comments) || 0));
  const total_likes = posts.reduce((s, p) => s + (Number(p.likes) || 0), 0);
  const total_comments = posts.reduce((s, p) => s + (Number(p.num_comments) || 0), 0);
  const mean_engagement = engagements.length
    ? engagements.reduce((s, n) => s + n, 0) / engagements.length
    : 0;

  const er_pct = followers ? (mean_engagement / followers) * 100 : 0;
  const comment_ratio_pct = total_likes ? (total_comments / total_likes) * 100 : 0;

  // Real posts land differently - one goes off, three do nothing. Engagement
  // that barely moves between posts is what a delivery service looks like, so
  // the spread is a signal and not just a statistic.
  let variation = null;
  if (engagements.length >= min_posts && mean_engagement > 0) {
    const sq = engagements.reduce((s, n) => s + Math.pow(n - mean_engagement, 2), 0) / engagements.length;
    variation = Math.sqrt(sq) / mean_engagement;
  }

  // `is_paid_partnership` is null on a post that is not one, so this counts
  // explicit trues rather than anything truthy.
  const sponsored = posts.filter((p) => p.is_paid_partnership === true).length;
  const sponsored_pct = posts.length ? (sponsored / posts.length) * 100 : 0;

  const newest = posts.length ? Date.parse(posts[0].date_posted) : NaN;
  const oldest = posts.length ? Date.parse(posts[posts.length - 1].date_posted) : NaN;
  const now = Date.parse($now.toISO());
  const days_since_post = isNaN(newest) ? null : Math.floor((now - newest) / 86400000);
  const span_days = isNaN(newest) || isNaN(oldest) ? null : Math.max(1, Math.round((newest - oldest) / 86400000));
  const posts_per_week = span_days ? round((posts.length / span_days) * 7, 1) : null;

  const cost_per_engagement = budget > 0 && mean_engagement > 0 ? budget / mean_engagement : null;

  if (profile.is_private === true) flags.push('private_account');
  if (posts.length < min_posts) flags.push('not_enough_posts');
  if (min_followers && followers < min_followers) flags.push('below_follower_band');
  if (max_followers && followers > max_followers) flags.push('above_follower_band');
  if (posts.length >= min_posts) {
    if (min_er && er_pct < min_er) flags.push('engagement_below_floor');
    if (max_er && er_pct > max_er) flags.push('engagement_implausibly_high');
    if (min_comment_ratio && comment_ratio_pct < min_comment_ratio) flags.push('likes_without_comments');
    if (variation !== null && variation < 0.15) flags.push('engagement_too_consistent');
    if (sponsored_pct > max_sponsored) flags.push('feed_is_mostly_ads');
  }
  if (max_quiet_days && days_since_post !== null && days_since_post > max_quiet_days) flags.push('gone_quiet');
  if (profile.is_joined_recently === true) flags.push('brand_new_account');
  if (followers && Number(profile.following) && followers / Number(profile.following) < 1) {
    flags.push('follows_more_than_follows_back');
  }

  const was = prior[d.handle] || null;

  out.push({
    json: {
      handle: d.handle,
      full_name: profile.full_name || profile.profile_name || '',
      profile_url: profile.profile_url || 'https://www.instagram.com/' + d.handle + '/',
      found: true,
      lane: 'judge',
      is_verified: profile.is_verified === true,
      is_private: profile.is_private === true,
      followers: followers,
      following: Number(profile.following) || 0,
      posts_count: Number(profile.posts_count) || 0,
      email_address: profile.email_address || '',
      biography: String(profile.biography || '').slice(0, 400),
      posts_read: posts.length,
      mean_engagement: Math.round(mean_engagement),
      er_pct: round(er_pct, 2),
      comment_ratio_pct: round(comment_ratio_pct, 2),
      variation: variation === null ? null : round(variation, 2),
      sponsored_pct: round(sponsored_pct, 0),
      days_since_post: days_since_post,
      posts_per_week: posts_per_week,
      cost_per_engagement: cost_per_engagement === null ? null : round(cost_per_engagement, 3),
      flags: flags,
      // Kept apart from the numbers on purpose: this is what the model reads.
      captions: posts.slice(0, 8).map((p) => String(p.description || '').slice(0, 300)).filter(Boolean),
      comment_sample: posts
        .slice(0, 4)
        .flatMap((p) => (Array.isArray(p.latest_comments) ? p.latest_comments.slice(0, 6) : []))
        .map((c) => String((c && c.comments) || '').slice(0, 160))
        .filter(Boolean)
        .slice(0, 20),
      prior_followers: was ? Number(was.followers) || null : null,
      prior_er_pct: was ? Number(was.er_pct) || null : null,
      prior_vetted_on: was ? was.vetted_on || '' : '',
      what_you_sell: clean.what_you_sell,
      budget_per_post: budget,
      coauthor_dropped: d.coauthor_dropped,
    },
  });
}
return out;

