const cfg = $('Settings').first().json;

// Four templates have now caught the model ignoring a schema's enum. This one
// ignored it in a new way, measured live on 2026-08-26: asked for one of
// strong/partial/none it answered "Excellent fit. Vercel directly provides
// deployment and hosting infrastructure for frontend teams..." - a correct
// judgement wearing the wrong shape, which an exact-match lookup turns into
// "unknown" and the verdict rules then ignore. So the prompt asks for one word
// and this reads the sentence anyway.
function normaliseFit(v) {
  const s = String(v || '').toLowerCase();
  if (!s) return 'unknown';
  if (/(no fit|poor|none|not relevant|no relevant|no connection|unrelated|irrelevant|no evidence)/.test(s)) return 'none';
  if (/(strong|excellent|direct|perfect|exact|clear fit|high)/.test(s)) return 'strong';
  if (/(partial|some |moderate|loose|adjacent|indirect|mixed|weak|tangential)/.test(s)) return 'partial';
  return 'unknown';
}

function normaliseComments(v) {
  const s = String(v || '').toLowerCase();
  if (!s) return 'unknown';
  // "cannot be assessed" is the honest answer on an account with no posts, and
  // it must not be read as a judgement about the comments.
  if (/(no comments|cannot be assessed|not provided|no data|insufficient)/.test(s)) return 'unknown';
  if (/(low.effort|low.signal|generic|emoji|mixed|inconsistent|superficial|shallow)/.test(s)) return 'mixed';
  if (/(bot|spam|fake|purchased|pod |inauthentic)/.test(s)) return 'bot';
  if (/(real|genuine|authentic|specific|substantive|thoughtful)/.test(s)) return 'real';
  return 'unknown';
}

const hard_flags = ['engagement_too_consistent', 'likes_without_comments', 'engagement_implausibly_high'];

// The Information Extractor REPLACES the item rather than merging into it, so
// every row arrives here as {output: {...}} and every number computed upstream
// has gone. The join back is positional, on the order the extractor received.
// Measured live on 2026-08-26: reading the fields off $json instead produced a
// report of three creators called "@undefined" with 0 followers, on a run where
// every node was green and the model's own answer was perfectly good.
const scored = $('Score The Engagement').all().map((x) => x.json);
const items = $input.all();

const out = [];
for (let i = 0; i < items.length; i++) {
  const d = scored[i];
  if (!d) continue;
  const judged = items[i].json || {};

  if (d.lane === 'no_data' || d.found === false) {
    // Dated like every other verdict. A remembered row with no date can never
    // be aged out, so a handle that was mistyped once would sit in the table
    // forever with nothing to say when it was tried.
    out.push({
      json: {
        ...d,
        verdict: 'no_data',
        worth_contacting: false,
        why: d.reason || 'nothing came back',
        vetted_on: String($now.toISODate()),
      },
    });
    continue;
  }

  // The Information Extractor nests its answer under `output`. Reading the
  // fields off $json directly gives undefined on every item, and the run stays
  // green while every verdict comes out empty.
  const read = (judged.output && typeof judged.output === 'object' ? judged.output : {}) || {};
  const comment_quality = normaliseComments(read.comment_quality);
  const niche_fit = normaliseFit(read.niche_fit);

  const flags = Array.isArray(d.flags) ? d.flags : [];
  const bought = flags.filter((f) => hard_flags.indexOf(f) !== -1);

  let verdict = 'maybe';
  const why = [];

  if (flags.indexOf('private_account') !== -1 || flags.indexOf('not_enough_posts') !== -1) {
    verdict = 'no_data';
    why.push('not enough public posts to judge');
  } else if (bought.length >= 2 || (bought.length === 1 && comment_quality === 'bot')) {
    verdict = 'avoid';
    why.push('engagement pattern does not look organic (' + bought.join(', ') + ')');
  } else if (niche_fit === 'none') {
    verdict = 'avoid';
    why.push('audience is not in your market');
  } else if (
    bought.length === 0 &&
    niche_fit === 'strong' &&
    comment_quality !== 'bot' &&
    flags.indexOf('gone_quiet') === -1 &&
    flags.indexOf('below_follower_band') === -1 &&
    flags.indexOf('above_follower_band') === -1
  ) {
    // Deliberately not requiring a comment section with no filler in it. Every
    // real account has emoji replies, and a rule that insists otherwise never
    // recommends anybody - which is a worse failure than recommending one
    // creator who turns out to be average.
    verdict = 'contact';
    why.push('in band, engagement looks organic, and the captions are about your market');
  }

  if (flags.indexOf('gone_quiet') !== -1) why.push('has not posted in ' + d.days_since_post + ' days');
  if (flags.indexOf('feed_is_mostly_ads') !== -1) why.push(d.sponsored_pct + '% of recent posts are already sponsored');
  if (flags.indexOf('below_follower_band') !== -1 || flags.indexOf('above_follower_band') !== -1) {
    why.push('outside the follower band you set');
  }
  // The model's concerns are kept apart from the verdict rather than appended
  // to it. Joined into one string they read as self-contradiction - "engagement
  // looks organic; the comment section includes spam" in a single sentence,
  // seen live on 2026-08-26. They are a caveat on the verdict, not part of it.
  const concerns = [];
  if (Array.isArray(read.concerns)) {
    for (const c of read.concerns.slice(0, 3)) {
      const text = String(c || '').trim();
      if (text && text.toLowerCase().indexOf('empty list') === -1) concerns.push(text);
    }
  }

  const movement = [];
  if (d.prior_followers) {
    const delta = d.followers - d.prior_followers;
    const pct = d.prior_followers ? Math.round((delta / d.prior_followers) * 1000) / 10 : 0;
    movement.push('followers ' + (delta >= 0 ? '+' : '') + pct + '% since ' + (d.prior_vetted_on || 'last time'));
  }
  if (d.prior_er_pct) {
    const delta = Math.round((d.er_pct - d.prior_er_pct) * 100) / 100;
    movement.push('engagement ' + (delta >= 0 ? '+' : '') + delta + ' points');
  }

  out.push({
    json: {
      ...d,
      verdict: verdict,
      worth_contacting: verdict === 'contact',
      comment_quality: comment_quality,
      niche_fit: niche_fit,
      audience_note: String(read.audience_note || '').slice(0, 300),
      content_note: String(read.content_note || '').slice(0, 300),
      outreach_angle: String(read.outreach_angle || '').slice(0, 300),
      why: why.length ? why.join('; ') : 'nothing stood out either way',
      concerns: concerns.join(' '),
      movement: movement.join(', '),
      vetted_on: String($now.toISODate()),
    },
  });
}

// Cheapest real engagement first. That ordering is the whole point - it is the
// only comparison that survives a difference in follower count.
out.sort((a, b) => {
  const av = a.json.cost_per_engagement;
  const bv = b.json.cost_per_engagement;
  if (av === null && bv === null) return 0;
  if (av === null) return 1;
  if (bv === null) return -1;
  return av - bv;
});
return out;

// One flat row per shortlisted creator. autoMapInputData writes whatever keys
// it is given, so the arrays and the caption text are dropped here rather than
// landing in the sheet as JSON blobs.
return $input.all().map((item) => {
  const d = item.json;
  return {
    json: {
      vetted_on: d.vetted_on,
      handle: d.handle,
      name: d.full_name,
      profile_url: d.profile_url,
      followers: d.followers,
      engagement_pct: d.er_pct,
      comment_ratio_pct: d.comment_ratio_pct,
      posts_per_week: d.posts_per_week,
      sponsored_pct: d.sponsored_pct,
      days_since_post: d.days_since_post,
      cost_per_engagement: d.cost_per_engagement,
      niche_fit: d.niche_fit,
      comment_quality: d.comment_quality,
      verdict: d.verdict,
      why: d.why,
      concerns: d.concerns,
      outreach_angle: d.outreach_angle,
      contact_email: d.email_address,
      flags: (d.flags || []).join(', '),
    },
  };
});

// The page whoever filled the form is left looking at. The Form ending node
// renders this raw, so it is real HTML rather than text - a report joined with
// newlines collapses into a single paragraph in the browser.
//
// Read from the verdict node rather than from $input. Both lanes feeding the
// Merge have been through a branch by then and one of them reshapes its items
// for the sheet, so $input here would be missing most of what this prints.
const clean = $('Clean The Handles').first().json;
const cfg = $('Settings').first().json;
const rows = $('Decide The Verdict').all().map((i) => i.json);

const F = 'system-ui,-apple-system,sans-serif';
const money = String(cfg.currency_symbol || '');
const budget = Number(clean.budget_per_post) || 0;

function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
const num = (v, dp) =>
  v === null || v === undefined || v === '' ? '-' : Number(v).toFixed(dp === undefined ? 2 : dp);

const order = { contact: 0, maybe: 1, avoid: 2, no_data: 3 };
const rank = (v) => (order[v] === undefined ? 9 : order[v]);
const cost = (v) => (v === null || v === undefined ? Infinity : v);
rows.sort((a, b) => rank(a.verdict) - rank(b.verdict) || cost(a.cost_per_engagement) - cost(b.cost_per_engagement));

const BADGE = {
  contact: ['Worth contacting', '#0a7d33'],
  maybe: ['Look closer', '#9a6700'],
  avoid: ['Pass', '#a11'],
  no_data: ['Could not read', '#777'],
};

const counts = { contact: 0, maybe: 0, avoid: 0, no_data: 0 };
const cards = rows
  .map((d) => {
    counts[d.verdict] = (counts[d.verdict] || 0) + 1;
    const badge = BADGE[d.verdict] || BADGE.no_data;
    const head =
      '<div style="margin:0 0 6px">' +
      '<span style="background:' + badge[1] + ';color:#fff;font-size:11px;letter-spacing:.4px;' +
      'text-transform:uppercase;padding:2px 7px;border-radius:3px">' + esc(badge[0]) + '</span>' +
      ' <a href="' + esc(d.profile_url) + '" style="font-weight:600;color:#111;text-decoration:none">@' +
      esc(d.handle) + '</a>' +
      (d.full_name ? '<span style="color:#666"> - ' + esc(d.full_name) + '</span>' : '') +
      '</div>';

    if (d.verdict === 'no_data') {
      return '<div style="border-left:3px solid #ddd;padding:2px 0 2px 12px;margin:0 0 16px;font:14px/1.55 ' + F + '">' +
        head + '<div style="color:#555">' + esc(d.why || d.reason || 'nothing came back') + '</div></div>';
    }

    const stat = (label, value) =>
      '<td style="padding:0 18px 0 0;vertical-align:top">' +
      '<div style="font-size:17px;color:#111">' + value + '</div>' +
      '<div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:.3px">' + label + '</div></td>';

    const stats =
      '<table style="border-collapse:collapse;margin:8px 0 6px"><tr>' +
      stat('followers', esc(Number(d.followers || 0).toLocaleString('en-US'))) +
      stat('engagement', num(d.er_pct) + '%') +
      stat('comments / 100 likes', num(d.comment_ratio_pct)) +
      (d.cost_per_engagement === null || d.cost_per_engagement === undefined
        ? stat('cost per engagement', '<span style="color:#888">set a budget</span>')
        : stat('per engagement at ' + esc(money + budget), esc(money) + num(d.cost_per_engagement, 3))) +
      (d.posts_per_week === null || d.posts_per_week === undefined ? '' : stat('posts / week', num(d.posts_per_week, 1))) +
      stat('sponsored', num(d.sponsored_pct, 0) + '%') +
      '</tr></table>';

    const line = (label, text, colour) =>
      text
        ? '<div style="color:' + (colour || '#333') + ';margin-top:4px">' +
          (label ? '<b>' + label + '</b> ' : '') + esc(text) + '</div>'
        : '';

    return '<div style="border-left:3px solid ' + badge[1] + ';padding:2px 0 2px 12px;margin:0 0 20px;font:14px/1.55 ' + F + '">' +
      head + stats +
      line('', d.why) +
      line('Concerns:', d.concerns, '#8a6d3b') +
      line('Movement:', d.movement, '#555') +
      line('Audience:', d.audience_note, '#555') +
      (d.verdict === 'contact' ? line('Open with:', d.outreach_angle, '#0a7d33') : '') +
      (d.email_address
        ? '<div style="margin-top:4px"><a href="mailto:' + esc(d.email_address) +
          '" style="color:#0a58ca">' + esc(d.email_address) + '</a></div>'
        : '') +
      ((d.flags || []).length
        ? '<div style="font-size:12px;color:#999;margin-top:6px">flags: ' + esc((d.flags || []).join(', ')) + '</div>'
        : '') +
      '</div>';
  })
  .join('');

const notes = [];
if ((clean.rejected || []).length) {
  notes.push('Not valid Instagram handles, so skipped: ' + esc(clean.rejected.join(', ')));
}
if ((clean.over_limit || []).length) {
  notes.push('Over the ' + esc(cfg.max_creators) + '-creator limit for one run, so not vetted: ' + esc(clean.over_limit.join(', ')));
}
const dropped = rows.length ? Number(rows[0].coauthor_dropped) || 0 : 0;
if (dropped) notes.push(dropped + ' post(s) came from a co-author account and were left out of the averages.');
if (rows.some((r) => r.timed_out)) {
  notes.push('Instagram did not finish in time for at least one job - run it again to fill the gaps.');
}
if (counts.contact) notes.push('The ' + counts.contact + ' worth contacting are in your shortlist sheet.');

const summary =
  counts.contact + ' worth contacting, ' + counts.maybe + ' worth a closer look, ' +
  counts.avoid + ' to pass on, ' + counts.no_data + ' unreadable.';

const html =
  '<div style="max-width:720px;margin:0 auto;text-align:left;font:15px/1.6 ' + F + '">' +
  '<h2 style="font-size:20px;margin:0 0 4px">Vetted ' + rows.length + ' creator' + (rows.length === 1 ? '' : 's') + '</h2>' +
  '<div style="color:#666;margin:0 0 4px">for ' + esc(clean.what_you_sell || 'an unspecified product') + '</div>' +
  '<div style="color:#111;margin:0 0 20px">' + esc(summary) + '</div>' +
  cards +
  (notes.length
    ? '<div style="font:13px/1.6 ' + F + ';color:#777;border-top:1px solid #eee;padding-top:10px">' +
      notes.map((t) => '<div>' + t + '</div>').join('') + '</div>'
    : '') +
  '<p style="font:12px ' + F + ';color:#999">Verdict first, then cheapest real engagement. Every rate ' +
  'is measured against the profile follower count, not the rounded figure the post rows carry.</p></div>';

return [{ json: { html: html, vetted: rows.length, shortlisted: counts.contact } }];
